// Shared dashboard pieces for light/dark wallpaper pairs, plus the "Wallpapers in the app" list.
//
// A pair is shown the way the app shows it: one picture split down the middle, the light version on the left and
// the dark version on the right. A wallpaper with a single image is shown normally.
//
// admin-catalog.json is generated by scripts/export_web_catalog.py. It names every built-in wallpaper but only points
// at images already published on the website; the rest show an "App only" tile.

const SOURCE = { original: "Original art", photo: "Licensed photo", supplied: "Your supplied picture" };

export const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

/** Markup for a picture: split in half when [dark] is given, plain otherwise. Sizing comes from the CSS class. */
export function pictureHtml(light, dark, cls = "") {
  if (!dark) return `<span class="pic ${cls}"><img src="${escapeHtml(light)}" alt="" loading="lazy" /></span>`;
  return `<span class="pic pair ${cls}"><img class="l" src="${escapeHtml(light)}" alt="" loading="lazy" />` +
    `<img class="d" src="${escapeHtml(dark)}" alt="" loading="lazy" /></span>`;
}

/** Full-size preview with Split / Day / Night views. [item] = { title, light, dark? }. */
export function openPreview(item) {
  let box = document.getElementById("preview");
  if (!box) {
    box = document.createElement("div");
    box.id = "preview";
    box.className = "overlay";
    document.body.appendChild(box);
    box.addEventListener("click", (e) => { if (e.target === box) box.hidden = true; });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") box.hidden = true; });
  }
  const pair = !!item.dark;
  box.innerHTML = `
    <div class="sheet" role="dialog" aria-label="${escapeHtml(item.title)}">
      <button class="x" aria-label="Close">×</button>
      <div class="stage" data-mode="${pair ? "split" : "day"}">
        <img class="l" src="${escapeHtml(item.light)}" alt="" />
        ${pair ? `<img class="d" src="${escapeHtml(item.dark)}" alt="" />` : ""}
      </div>
      <div class="t">${escapeHtml(item.title)}</div>
      ${pair ? `<div class="seg">
        <button data-mode="split" class="on">Split</button>
        <button data-mode="day">Day (light)</button>
        <button data-mode="night">Night (dark)</button></div>`
        : '<div class="muted" style="text-align:center">One image for both day and night.</div>'}
    </div>`;
  box.querySelector(".x").onclick = () => { box.hidden = true; };
  const stage = box.querySelector(".stage");
  box.querySelectorAll(".seg button").forEach((b) => {
    b.onclick = () => {
      stage.dataset.mode = b.dataset.mode;
      box.querySelectorAll(".seg button").forEach((o) => o.classList.toggle("on", o === b));
    };
  });
  box.hidden = false;
}

export async function mountBuiltIn() {
  const $ = (id) => document.getElementById(id);
  let data;
  try {
    const res = await fetch("admin-catalog.json", { cache: "no-cache" });
    if (!res.ok) throw new Error(String(res.status));
    data = await res.json();
  } catch (e) {
    $("builtInGrid").innerHTML =
      '<span class="muted">Couldn\'t load the app\'s wallpaper list. It is created when the site is deployed.</span>';
    return;
  }
  const catTitle = Object.fromEntries(data.categories.map((c) => [c.id, `${c.emoji} ${c.title}`]));
  const counts = {};
  for (const w of data.wallpapers) counts[w.cat] = (counts[w.cat] || 0) + 1;
  $("statBuiltIn").textContent = data.wallpapers.length;
  $("statPairs").textContent = data.wallpapers.filter((w) => w.both).length;
  let current = "", source = "", kind = "";

  const thumbs = (w) => w.web
    ? { light: w.both ? `app/img/t/${encodeURIComponent(w.id)}~l.webp` : `app/img/t/${encodeURIComponent(w.id)}.webp`,
        dark: w.both ? `app/img/t/${encodeURIComponent(w.id)}.webp` : null }
    : null;

  function render() {
    const q = ($("builtInSearch").value || "").trim().toLowerCase();
    const chips = [["", `All ${data.wallpapers.length}`], ...data.categories.map((c) => [c.id, `${catTitle[c.id]} ${counts[c.id] || 0}`])];
    $("builtInCats").innerHTML = chips
      .map(([id, label]) => `<span class="chip${id === current ? " on" : ""}" data-cat="${id}">${escapeHtml(label)}</span>`)
      .join("");
    $("builtInCats").querySelectorAll("[data-cat]").forEach((el) => {
      el.onclick = () => { current = el.dataset.cat; render(); };
    });
    const sources = [["", "Any source"], ...Object.entries(SOURCE).map(([id, label]) =>
      [id, `${label} ${data.wallpapers.filter((w) => w.source === id).length}`])];
    const kinds = [["", "Pairs and singles"], ["pair", `Light + dark ${data.wallpapers.filter((w) => w.both).length}`],
      ["single", `One image ${data.wallpapers.filter((w) => !w.both).length}`]];
    $("builtInSources").innerHTML = [...sources.map(([id, l]) => ["source", id, l]), ...kinds.map(([id, l]) => ["kind", id, l])]
      .map(([group, id, label]) => `<span class="chip${(group === "source" ? id === source : id === kind) ? " on" : ""}" data-${group}="${id}">${escapeHtml(label)}</span>`)
      .join("");
    $("builtInSources").querySelectorAll("[data-source]").forEach((el) => { el.onclick = () => { source = el.dataset.source; render(); }; });
    $("builtInSources").querySelectorAll("[data-kind]").forEach((el) => { el.onclick = () => { kind = el.dataset.kind; render(); }; });

    const items = data.wallpapers.filter((w) =>
      (!current || w.cat === current) && (!source || w.source === source) &&
      (!kind || (kind === "pair") === w.both) &&
      (!q || w.title.toLowerCase().includes(q) || w.id.includes(q)));
    $("builtInCount").textContent = `· ${items.length} shown`;
    $("builtInGrid").innerHTML = items.length
      ? items.map((w) => {
          const t = thumbs(w);
          return `
          <div class="tile" data-id="${escapeHtml(w.id)}" title="${escapeHtml(w.id)}">
            ${t ? pictureHtml(t.light, t.dark, "tilepic") : '<div class="ph">App only<br>kept off the website</div>'}
            <div class="t">${escapeHtml(w.title)}</div>
            <div class="s">${escapeHtml(catTitle[w.cat] || w.cat)}</div>
            <div class="s">${w.both ? "Light + dark" : "One image"} · ${escapeHtml(SOURCE[w.source] || w.source)} · ${w.web ? "app + web" : "app only"}</div>
          </div>`;
        }).join("")
      : '<span class="muted">No matching wallpapers.</span>';
    $("builtInGrid").querySelectorAll(".tile").forEach((el) => {
      const w = data.wallpapers.find((x) => x.id === el.dataset.id);
      if (!w || !w.web) return;
      el.style.cursor = "pointer";
      el.onclick = () => openPreview({
        title: w.title,
        light: w.both ? `app/img/f/${encodeURIComponent(w.id)}~l.webp` : `app/img/f/${encodeURIComponent(w.id)}.webp`,
        dark: w.both ? `app/img/f/${encodeURIComponent(w.id)}.webp` : null,
      });
    });
  }
  $("builtInSearch").oninput = render;
  render();
}
